from taf.ul.ettf.utils.exception import LibraryError
from taf.ul.ettf.utils import exception_causes
from taf.ul.ettf.utils.robot_handlers import with_callback_name
from abc import ABCMeta, abstractmethod
from future.utils import with_metaclass


class StorageError(LibraryError):
    pass


class StoragePolicy(with_metaclass(ABCMeta, object)):
    @abstractmethod
    def store(self, key, value, storage):
        pass

    @abstractmethod
    def get(self, key, storage):
        pass


class StoreValue(StoragePolicy):
    def store(self, key, value, storage):
        if key in storage:
            raise StorageError(exception_causes.DUPLICATED_KEY, 'Value with given key ({}) is already stored.'.format(key))
        storage[key] = value

    def get(self, key, storage):
        return storage.pop(key)


class StoreValueWithUpdate(StoragePolicy):
    def store(self, key, value, storage):
        storage[key] = value

    def get(self, key, storage):
        return storage[key]


class AppendToList(StoragePolicy):
    def store(self, key, value, storage):
        if key in storage:
            storage[key].append(value)
        else:
            storage[key] = [value]

    def get(self, key, storage):
        return storage.pop(key)


class Storage(object):
    def __init__(self):
        self.storage = {}
        self.key_policy_mapping = {}

    def store(self, key, value, storage_policy=StoreValue):
        storage_policy().store(key, value, self.storage)
        self.key_policy_mapping[key] = storage_policy

    def get(self, key):
        if key not in self.storage:
            raise StorageError(exception_causes.DOES_NOT_EXIST, 'Value with given key ({}) does not exist in storage.'.format(key))

        return self.key_policy_mapping[key]().get(key, self.storage)

    def contains(self, key):
        return key in self.storage

    @with_callback_name('Msg Capture Storage Teardown')
    def teardown(self):
        self.storage = {}
        self.key_policy_mapping = {}
